  "gas_based_value_refined": {
  "metric": "declaration_gas_cost_usd / declaration_value_usd（gas价值占比）",
  "high_value_trigger": "gas价值占比 < 0.01%（声明者愿意用极低成本保护高价值资产）",
  "cross_chain_normalization": "统一转换为USD计价，消除不同链gas基准差异",
